// StockPilot: guided data preparation, explainable recommendations and order lifecycle.
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=0)=>v===null||v===undefined||!Number.isFinite(Number(v))?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:d}).format(v);
const dateText=v=>v?new Date(String(v).length===10?v+'T12:00:00':v).toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'}):'Не указана';
const sourceLabels={sales:'Продажи',stock:'Остатки',transit:'Поставки в пути'};
const orderLabels={draft:'Черновик',approved:'Размещён',received:'Получен',cancelled:'Отменён'};
const pageSize=12,selectedIds=new Set();
let state,filtered=[],supplier='',page=0,currentId=null,busy=false,chatHistory=[],uploadPreview=null,importBusy=false,uploadKind='sales',activeView='home';
let orderData={orders:[],summary:{}},orderFilter='all',orderLoading=false,activeOrder=null;
let anomalyData={items:[],summary:{}},anomalyPage=0,anomalyLoading=false,backtestResult=null,confirmAction=null;
function toast(message){$('#toast').textContent=message;$('#toast').classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.add('hidden'),6500);}
async function api(path,body){const response=await fetch(path,{method:body!==undefined?'POST':'GET',headers:body!==undefined?{'Content-Type':'application/json','X-CSRF-Token':state?.csrf||''}:{},body:body!==undefined?JSON.stringify(body):undefined});let data;try{data=await response.json()}catch{throw Error('Сервер не ответил. Проверьте, запущено ли приложение.')}if(!response.ok)throw Error(data.error||'Не удалось выполнить запрос');return data;}
async function runButton(button,work,label='Сохраняем…'){const before=button.textContent;button.disabled=true;button.textContent=label;try{return await work()}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent=before;if(button.id==='create-orders')renderSelection()}}
function emptyState(title,text,view){return `<div class="empty-state"><span class="empty-icon">▧</span><h2>${esc(title)}</h2><p>${esc(text)}</p>${view?`<button class="button secondary" data-open-view="${esc(view)}">Перейти к анализу →</button>`:''}</div>`;}
function invalidateBacktest(){if(backtestResult){backtestResult=null;$('#backtest-content').innerHTML=emptyState('Данные изменились','Запустите проверку снова, чтобы сравнить прогноз на актуальных данных.');}}
async function refresh(){state=await api('/api/state');const selected=$('#category-filter').value;$('#category-filter').innerHTML='<option value="">Все категории</option>'+state.categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');$('#category-filter').value=state.categories.includes(selected)?selected:'';const valid=new Set(state.rows.filter(canOrder).map(r=>r.id));for(const id of selectedIds)if(!valid.has(id))selectedIds.delete(id);renderSuppliers();renderStats();renderRows();renderQuality();renderHome();renderSources();renderAutomation();$('#data-mode').textContent=state.mode==='demo'?'Тестовый пример':state.mode==='upload'?'Ваши данные':'Данные кейса';$('#date-settings').textContent='Расчёт на '+dateText(state.settings.as_of);$('#agent-mode').textContent=state.agent==='live'?'ИИ подключён · функции расчёта':'Демо-помощник · готовые сценарии';$('#agent-footnote').textContent=state.agent==='live'?'ИИ получает вопрос и результаты выбранных функций. Решение о заказе принимаете вы.':'Сейчас работает помощник по готовым сценариям. Для свободного диалога нужен подключённый ИИ.';$('#choose-file').disabled=false;$('#continue-analysis').disabled=false;const n=state.orders_summary?.draft||0;$('#nav-order-count').textContent=fmt(n);$('#nav-order-count').classList.toggle('hidden',!n);}
function renderSuppliers(){const suppliers=[...new Set(state.rows.map(r=>r.supplier))].sort();if(!suppliers.includes(supplier))supplier='';$('#supplier-tabs').innerHTML=['',...suppliers].map(s=>`<button class="supplier ${s===supplier?'active':''}" data-supplier="${esc(s)}" aria-pressed="${s===supplier}">${esc(s||'Все поставщики')}</button>`).join('');}
function renderHome(){const title=state.mode==='upload'?(state.upload?.file||'Загруженные таблицы'):state.mode==='demo'?'Пример на тестовых данных':'Данные кейса · Электрокомплект';$('#current-dataset-title').textContent=title;$('#current-dataset-info').textContent=`${fmt(state.summary.items)} товаров · ${fmt(state.summary.to_order)} к заказу · ${fmt(state.summary.with_outliers)} со всплесками`;$('#restore-original').classList.toggle('hidden',!state.available_partner||state.mode==='partner');$('#restore-original').textContent='Открыть данные кейса';$('#restore-upload').classList.toggle('hidden',state.mode==='upload'||!state.available_upload);$('#open-demo').classList.toggle('hidden',state.mode==='demo');const known=state.summary.items-state.summary.missing_stock;$('#home-readiness').innerHTML=`<button data-open-view="quality"><span class="small-dot"></span>История продаж загружена</button><button data-open-view="quality"><span class="small-dot ${known<state.summary.items?'amber':''}"></span>Остаток: ${fmt(known)} из ${fmt(state.summary.items)} товаров</button><button data-open-view="purchase">Черновиков заказов: ${fmt(state.orders_summary?.draft||0)} <span>→</span></button>`;$('#analysis-context').innerHTML=`<div><span class="eyebrow">ТЕКУЩИЙ АНАЛИЗ</span><strong>${esc(title)}</strong><span>${fmt(state.summary.items)} товаров · ${new Set(state.rows.map(r=>r.supplier)).size} поставщиков${state.summary.missing_stock?' · Без остатка: '+fmt(state.summary.missing_stock):''}</span></div><button class="text-button" data-open-view="quality">Проверить данные ↗</button>`;$('#table-note').textContent='Спрос рассчитан по завершённым месяцам. Черновики резервируют количество для нового заказа, размещённые заказы учитываются как поставки. Предварительные рекомендации требуют сверки.';}
function showView(view){const labels={home:['','Главная',''],orders:['Анализ продаж','Анализ продаж','Сколько продадим, что есть на складе и сколько нужно заказать.'],quality:['Данные для уверенных закупок','Данные','Загрузите таблицы один раз — все рекомендации пересчитаются автоматически.'],anomalies:['Отделите разовый спрос','Проверка всплесков','Проверьте необычные продажи до формирования заказов.'],purchase:['Заказы поставщикам','Заказы поставщикам','Черновик, размещение, получение — вся история закупки в одном месте.'],backtest:['Проверьте качество прогноза','Качество прогноза','Сравнение с реальными продажами, которые алгоритм заранее не видел.'],method:['От таблицы к заказу','Как это работает','Пошаговая инструкция и понятная логика расчёта.']};if(!labels[view])view='home';activeView=view;$$('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.view===view);if(n.dataset.view===view)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});$$('.view').forEach(v=>v.classList.toggle('hidden',v.id!==view+'-view'));$('.page-heading').classList.toggle('hidden',view==='home');$('#page-title').textContent=labels[view][0];$('#breadcrumb').textContent=labels[view][1];$('#page-subtitle').textContent=labels[view][2];$('.heading-actions').classList.toggle('hidden',view!=='orders');history.replaceState(null,'','#'+view);window.scrollTo({top:0,behavior:'smooth'});if(state&&view==='purchase')loadOrders();if(state&&view==='anomalies')loadAnomalies();}
function renderStats(){const s=state.summary;$('#stats').innerHTML=[['Позиций к заказу',s.to_order,'Из '+fmt(s.items)+' товаров в каталоге','green','↗','order'],['Риск дефицита',s.urgent,'До нового поступления','orange','◷','urgent'],['Есть всплески',s.with_outliers,'Можно проверить решение','green','⌁','outlier'],['Остаток неизвестен',s.missing_stock,'Загрузите актуальную ведомость','','◈','missing']].map(([label,value,foot,color,icon,filter])=>`<button class="stat" data-filter="${filter}" aria-label="${label}: ${fmt(value)}. Показать товары"><span class="stat-label">${label}<span aria-hidden="true">${icon}</span></span><span class="stat-value">${fmt(value)}</span><span class="stat-foot ${color}">${foot}</span></button>`).join('');$$('#stats [data-filter]').forEach(b=>b.addEventListener('click',()=>{supplier='';page=0;$('#search').value='';$('#category-filter').value='';$('#status-filter').value=b.dataset.filter;renderSuppliers();renderRows();$('.orders-panel').scrollIntoView({behavior:'smooth',block:'start'})}));}
function availableQty(r){return Math.max(0,Number(r.available_to_order??((r.review?.qty??r.qty??0)-(r.draft_qty||0))));}
function canOrder(r){return r.stock!==null&&availableQty(r)>0;}
function renderRows(){if(!state)return;const query=$('#search').value.toLowerCase().trim(),filter=$('#status-filter').value,category=$('#category-filter').value;filtered=state.rows.filter(r=>(!supplier||r.supplier===supplier)&&(!category||r.category===category)&&(!query||(r.name+' '+r.article+' '+r.code).toLowerCase().includes(query))&&({all:true,order:r.qty>0,urgent:r.urgency==='Срочно',missing:r.stock===null,preliminary:r.status==='Предварительно',outlier:r.removed>0,approved:!!r.review}[filter]));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/pageSize)-1));const visible=filtered.slice(page*pageSize,(page+1)*pageSize);$('#result-count').textContent=fmt(filtered.length);$('#rows').innerHTML=visible.length?visible.map(r=>`<tr class="table-row" data-id="${esc(r.id)}"><td class="check-cell"><input type="checkbox" data-select-id="${esc(r.id)}" aria-label="Выбрать ${esc(r.article||r.code)}" ${selectedIds.has(r.id)?'checked':''} ${canOrder(r)?'':'disabled'}></td><td class="product-cell"><button class="product-link" data-item="${esc(r.id)}"><span class="product-title">${esc(r.article||r.code)}</span><span class="product-name">${esc(r.name)}</span></button><div class="product-meta">${esc(r.supplier)} · ${esc(r.category)}</div></td><td class="num">${fmt(r.monthly,1)}<div class="product-meta">${esc(r.unit)}</div></td><td class="num">${fmt(r.stock)}<div class="product-meta">${r.status==='Предварительно'?'на '+esc(r.stock_date):esc(r.unit)}</div></td><td class="num">${fmt(r.in_transit)}</td><td class="num qty">${fmt(r.review?r.review.qty:r.qty)}<small>${esc(r.unit)}</small>${r.draft_qty?`<span class="product-meta">${fmt(r.draft_qty)} в черновике</span>`:''}${r.review?'<span class="approved">проверено</span>':''}</td><td><span class="badge ${r.urgency==='Срочно'?'urgent':r.urgency==='Нет остатка'?'missing':'plan'}">${esc(r.urgency)}</span>${r.status==='Предварительно'?'<div class="product-meta">нужно сверить</div>':''}</td><td><button class="row-arrow" data-item="${esc(r.id)}" aria-label="Открыть расчёт ${esc(r.article||r.code)}">↗</button></td></tr>`).join(''):'<tr><td colspan="8" class="empty">По этим условиям товаров нет. Измените фильтр или загрузите данные.</td></tr>';$('#page-info').textContent=filtered.length?`${page*pageSize+1}–${Math.min((page+1)*pageSize,filtered.length)} из ${fmt(filtered.length)} товаров`:'Нет результатов';$('#prev').disabled=page===0;$('#next').disabled=(page+1)*pageSize>=filtered.length;$('#export').disabled=!filtered.length;const eligible=visible.filter(canOrder),checked=eligible.filter(r=>selectedIds.has(r.id)).length;$('#select-page').checked=eligible.length>0&&checked===eligible.length;$('#select-page').indeterminate=checked>0&&checked<eligible.length;$('#select-page').disabled=!eligible.length;renderSelection();}
function renderSelection(){const count=selectedIds.size||filtered.filter(canOrder).length;$('#selection-info').textContent=selectedIds.size?`Выбрано товаров: ${fmt(selectedIds.size)}`:`Для нового заказа по фильтру: ${fmt(count)}`;$('#clear-selection').classList.toggle('hidden',!selectedIds.size);$('#create-orders').disabled=!count;$('#create-orders').textContent='Сформировать заказы'+(count?' · '+fmt(count):'');}
function renderSources(){const s=state.summary,known=s.items-s.missing_stock;const specs=[['sales','01','История продаж','Показывает, что и сколько продаётся. По операциям или по месяцам.','Код товара · дата · количество',s.items>0?`${fmt(s.items)} товаров в расчёте`:'Нужна для начала'],['stock','02','Свободные остатки','Помогают не заказывать то, что уже есть на складе.','Код товара · свободный остаток',`${fmt(known)} из ${fmt(s.items)} товаров с остатком`],['transit','03','Ожидаемые поставки','Учитывают товары, которые уже заказаны и скоро поступят.','Код товара · количество · дата прихода','Добавьте при наличии поставок']];$('#source-cards').innerHTML=specs.map(([kind,step,title,help,fields,status])=>{const info=state.source_imports?.[kind];return `<article class="source-card"><div class="source-top"><span class="home-step">${step}</span><span class="badge ${info?'plan':''}">${info?'Загружено':kind==='sales'?'Первый шаг':kind==='transit'?'Если есть поставки':'Для расчёта заказа'}</span></div><h2>${title}</h2><p>${help}</p><div class="source-fields">${fields}<br><span>+ поставщик для точного сопоставления</span></div><div class="source-state"><span class="small-dot ${kind==='stock'&&known<s.items?'amber':''}"></span>${esc(info?.file||status)}${info?`<small>${info.row_count===null||info.row_count===undefined?'Исходный набор':fmt(info.row_count)+' строк'}${info.imported_at||info.as_of?' · '+dateText(info.imported_at||info.as_of):''}</small>`:''}</div><button class="button ${kind==='sales'?'primary':'secondary'}" data-upload-kind="${kind}">↑ ${info?'Обновить':'Загрузить'} ${kind==='transit'?'поставки':kind==='stock'?'остатки':'продажи'}</button><a class="template-link" href="/api/import/template?kind=${kind}" download>Скачать образец ↓</a><p class="source-warning">${kind==='sales'?'Новая история заменяет текущую загрузку. Данные кейса сохраняются.':kind==='stock'?'Полный снимок: отсутствующие в файле остатки станут неизвестны.':'Полный снимок: прошлые поставки заменяются. Номер заказа помогает избежать двойного учёта.'}</p></article>`}).join('');}
function renderQuality(){const d=state.diagnostics||{},suppliers=[...new Set(state.rows.map(r=>r.supplier))];$('#quality-content').innerHTML=`<div class="supplier-cards">${suppliers.map(name=>{const rows=state.rows.filter(r=>r.supplier===name);return `<article class="content-card"><div class="eyebrow">ПОСТАВЩИК</div><h2>${esc(name)}</h2><div class="supplier-total">${fmt(rows.length)} <span>товаров</span></div><div class="coverage-row"><span>Остаток известен</span><strong>${fmt(rows.filter(r=>r.stock!==null).length)} из ${fmt(rows.length)}</strong></div><div class="coverage-row"><span>Даты остатков</span><strong>${[...new Set(rows.map(r=>r.stock_date).filter(Boolean))].sort().map(esc).join(' / ')||'Не указаны'}</strong></div></article>`}).join('')}</div><div class="content-card"><h2>Что известно о данных</h2><p>${state.mode==='demo'?'Это синтетические данные для знакомства с программой.':state.mode==='upload'?'Таблицы загружены вами. Товары объединены по поставщику и коду.':'Выгрузки материалов кейса объединены по поставщику и коду 1С.'}</p><div class="mini-metrics"><span>Строк продаж: <b>${fmt(d.imported_rows??d.transaction_rows)}</b></span><span>Отрицательных корректировок: <b>${fmt(d.negative_adjustments)}</b></span></div><ul class="quality-list">${(state.limitations||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div><div class="content-card"><h2>Исходные файлы</h2><div class="table-scroll"><table class="quality-files"><thead><tr><th>Файл</th><th>Поставщик</th><th>Размер</th></tr></thead><tbody>${(state.sources||[]).map(s=>`<tr><td>${esc(s.file)}${s.sha256?`<small>Контрольная сумма: ${esc(s.sha256.slice(0,16))}…</small>`:''}</td><td>${esc(s.supplier||'По данным файла')}</td><td>${fmt(s.bytes/1024)} КБ</td></tr>`).join('')||'<tr><td colspan="3">Исходных файлов нет: используется встроенный пример.</td></tr>'}</tbody></table></div></div>`;}
function renderAutomation(force=false){const raw=state.automation||{},a={...raw,...raw.config},f=$('#automation-form');if(force||!f.contains(document.activeElement)){f.elements.folder.value=a.folder||'';f.elements.interval_minutes.value=String(a.interval_minutes||60);f.elements.enabled.checked=!!a.enabled;f.elements.advance_date.checked=!!a.advance_date;}$('#automation-badge').textContent=a.enabled?'Включено':'Выключено';$('#automation-badge').className='badge '+(a.enabled?'plan':'');const status=typeof raw.status==='object'?raw.status:raw;$('#automation-status').innerHTML=`<div class="mini-metrics"><span>Последнее обновление: <b>${status.last_run?esc(new Date(status.last_run).toLocaleString('ru-RU')):'ещё не запускалось'}</b></span>${status.next_run?`<span>Следующее: <b>${esc(new Date(status.next_run).toLocaleString('ru-RU'))}</b></span>`:''}</div>${status.last_error?`<p class="import-error">${esc(status.last_error)}</p>`:''}${(state.notifications||raw.notifications||status.notifications||[]).length?`<ul class="activity-list">${(state.notifications||raw.notifications||status.notifications||[]).slice(-5).reverse().map(n=>`<li>${esc(typeof n==='string'?n:n.message||n.text||(n.title? n.title+(n.detail?' · '+n.detail:''):'Рекомендации обновлены'))}</li>`).join('')}</ul>`:''}`;}
function chart(history){if(!history.length)return '<p class="muted">Недостаточно истории</p>';const w=750,h=175,left=45,right=16,top=12,bottom=28;const max=Math.max(1,...history.map(h=>Math.max(h.raw,h.corrected)))*1.1;const x=i=>left+i*(w-left-right)/Math.max(1,history.length-1),y=v=>h-bottom-v/max*(h-top-bottom);let result=`<svg viewBox="0 0 ${w} ${h}" class="chart" role="img" aria-label="История фактических и скорректированных продаж">`;for(let i=0;i<4;i++){let v=max*i/3;result+=`<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#e8efed"/><text x="${left-8}" y="${y(v)+3}" text-anchor="end">${fmt(v)}</text>`}for(const [key,color,width]of[['raw','#b5c4ca',2],['corrected','#2b9872',2.4]])result+=`<polyline fill="none" stroke="${color}" stroke-width="${width}" stroke-linejoin="round" points="${history.map((v,i)=>x(i)+','+y(v[key])).join(' ')}"/>`;history.forEach((v,i)=>{if(i%4===0||i===history.length-1)result+=`<text x="${x(i)}" y="${h-6}" text-anchor="middle">${esc(v.month.slice(5)+'.'+v.month.slice(2,4))}</text>`});return result+'</svg>'}
async function openItem(id){try{currentId=id;const r=await api('/api/item?id='+encodeURIComponent(id));$('#item-content').innerHTML=`<div class="dialog-heading"><div><div class="eyebrow">${esc(r.article||r.code)}<span class="item-supplier">${esc(r.supplier)}</span></div><h2>${esc(r.name)}</h2></div><button class="icon-button close-dialog" aria-label="Закрыть">×</button></div><div class="item-subtitle">Код 1С: ${esc(r.code)} · ${esc(r.category)} · ${esc(r.unit||'единица не указана')} · ${esc(r.status)}</div><div class="equation"><div><span>Спрос за ${r.horizon_days} дн.</span><strong>${fmt(r.demand,1)}</strong></div><div><span>Страховой запас</span><strong>+ ${fmt(r.safety,1)}</strong></div><div><span>Остаток + поступления</span><strong>− ${r.stock===null?'?':fmt(r.stock+r.in_transit,1)}</strong></div><div><span>Рекомендуем заказать</span><strong>${fmt(r.qty)}</strong> <small>${esc(r.unit)}</small></div></div><p class="detail-reason">${esc(r.reason)}</p><div class="mini-metrics"><span>Устойчивый тренд: <b>${fmt(r.growth*100,1)}%</b></span><span>Исключено всплесков: <b>${fmt(r.removed,1)} ${esc(r.unit)}</b></span><span>Восстановлено спроса: <b>${fmt(r.lost,1)} ${esc(r.unit)}</b></span></div><div class="chart-title"><strong>Продажи по полным месяцам · ${esc(r.unit)}</strong><span class="legend">Факт</span><span class="legend corrected">Регулярный спрос</span></div>${chart(r.history)}<ul class="detail-warnings">${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul><details class="detail-sources"><summary>Поставки и источники расчёта</summary>${r.transit.length?'<ul>'+r.transit.map(t=>`<li>${esc(t.eta||'Нет даты')}: ${fmt(t.qty)} ${esc(r.unit)}</li>`).join('')+'</ul>':'<p>Поставок нет</p>'}<ul>${r.sources.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>${r.source_growth!==null&&r.source_growth!==undefined?`<p>Рост из ведомости (для сверки): ${fmt(r.source_growth*100,1)}%. В прогнозе используется собственная оценка по очищенным данным.</p>`:''}</details><details class="review-section" ${r.status!=='Черновик'?'open':''}><summary>Сверить остаток и кратность</summary><form id="stock-form"><div class="review-inline"><label>Свободный остаток<input id="actual-stock" type="number" min="0" max="1000000000" step="any" required value="${r.stock===null?'':r.stock}"></label><label>Кратность<input id="actual-pack" type="number" min="0.0001" max="1000000" step="any" required value="${r.pack}"></label><button class="button secondary" type="submit">Обновить расчёт</button></div><label class="confirm"><input id="stock-confirmed" type="checkbox" required>Остаток подтверждён на ${esc(state.settings.as_of)}; кратность в единицах учёта</label></form></details><div class="review-section"><h3>Проверка менеджером</h3><form id="review-form"><div class="review-inline"><label>Количество к заказу<input id="final-qty" type="number" min="0" max="1000000000" step="any" required value="${r.review?r.review.qty:r.qty??''}"></label><label>Комментарий<input id="review-note" maxlength="500" placeholder="Причина корректировки" value="${esc(r.review?.note||'')}"></label><button class="button primary" type="submit" ${r.status!=='Черновик'?'disabled':''}>Утвердить строку</button></div><label class="confirm"><input id="review-confirmed" type="checkbox" required>Количество, единицы, минимум и сроки поставки проверены</label></form><div class="detail-foot">Утверждение сохраняется локально. Заказ поставщику не отправляется.${r.review?' Утверждено: '+esc(r.review.at):''}</div></div><div class="dialog-actions"><button id="explain-with-agent" class="button secondary">✦ Объяснить с агентом</button><button class="button secondary close-dialog">Закрыть</button></div>`;
  $$('#item-dialog .close-dialog').forEach(b=>b.addEventListener('click',()=>$('#item-dialog').close()));if(!$('#item-dialog').open)$('#item-dialog').showModal();
  $('#stock-form').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/override',{id,stock:Number($('#actual-stock').value),pack:Number($('#actual-pack').value),confirmed:$('#stock-confirmed').checked});await refresh();await openItem(id);toast('Остаток обновлён, рекомендация пересчитана')}catch(err){toast(err.message)}});
  $('#review-form').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/review',{id,qty:Number($('#final-qty').value),note:$('#review-note').value,confirmed:$('#review-confirmed').checked});await refresh();await openItem(id);toast('Строка утверждена локально')}catch(err){toast(err.message)}});
  $('#explain-with-agent').addEventListener('click',()=>{$('#item-dialog').close();showView('orders');sendMessage('Объясни расчёт для '+(r.article||r.code));});
}catch(err){toast(err.message)}}
async function sendMessage(message){if(busy||!message.trim())return;busy=true;$('#chat-send').disabled=true;$('#message').value='';const user=document.createElement('div');user.className='user-message';user.textContent=message;$('#chat').append(user);const reply=document.createElement('div');reply.className='assistant-message';reply.textContent='Проверяю расчёт…';$('#chat').append(reply);$('#chat').scrollTop=$('#chat').scrollHeight;try{const response=await api('/api/agent',{message,history:chatHistory});reply.innerHTML=`<div class="chat-label">${response.mode==='live'?'ИИ-АГЕНТ':'ДЕМО-ПОМОЩНИК'}</div>${esc(response.answer)}${response.trace.length?`<details class="trace"><summary>Выполнено действий: ${response.trace.length}</summary>${response.trace.map(t=>`${esc(t.tool)} ${esc(JSON.stringify(t.arguments))}`).join('<br>')}</details>`:''}`;chatHistory.push({role:'user',content:message},{role:'assistant',content:response.answer});chatHistory=chatHistory.slice(-8);}catch(err){reply.textContent=err.message;reply.classList.add('error')}finally{busy=false;$('#chat-send').disabled=false;$('#chat').scrollTop=$('#chat').scrollHeight}}


// Persisted purchase orders. A draft is reviewable; changing status is explicit.
async function loadOrders(){if(orderLoading)return;orderLoading=true;if(!orderData.orders.length)$('#purchase-content').innerHTML='<div class="loading-state">Загружаем заказы…</div>';try{orderData=await api('/api/orders');renderOrders()}catch(e){$('#purchase-content').innerHTML=emptyState('Не удалось загрузить заказы',e.message);toast(e.message)}finally{orderLoading=false}}
function renderOrders(){const summary=orderData.summary||{};$('#purchase-summary').innerHTML=[['draft','Черновики','Проверьте и разместите'],['approved','Размещены','Ожидаем поступления'],['received','Получены','Товар добавлен на склад'],['cancelled','Отменены','Сохранены в истории']].map(([k,label,help])=>`<button class="compact-stat" data-order-status="${k}"><span>${label}</span><strong>${fmt(summary[k]??orderData.orders.filter(o=>o.status===k).length)}</strong><small>${help}</small></button>`).join('');$$('#purchase-filters button').forEach(b=>b.classList.toggle('active',b.dataset.orderStatus===orderFilter));const orders=orderData.orders.filter(o=>orderFilter==='all'||o.status===orderFilter);$('#purchase-content').innerHTML=orders.length?orders.map(o=>`<article class="purchase-card"><div class="purchase-card-top"><span class="badge order-${esc(o.status)}">${esc(orderLabels[o.status]||o.status)}</span><span class="muted">${dateText(o.created_at)}</span></div><h2>${esc(o.supplier)}</h2><div class="order-number">${esc(o.number||o.id)}</div><div class="order-facts"><span>Позиций <strong>${fmt(o.lines.length)}</strong></span><span>Ожидаем <strong>${dateText(o.expected_at)}</strong></span></div><p class="order-preview">${o.lines.slice(0,2).map(l=>esc(l.article||l.code)+' · '+fmt(l.qty)+' '+esc(l.unit)).join('<br>')}${o.lines.length>2?`<br>и ещё ${fmt(o.lines.length-2)} позиций`:''}</p>${o.warnings?.length?`<span class="inline-warning">${fmt(o.warnings.length)} замечаний к проверке</span>`:''}<button class="button secondary" data-order-id="${esc(o.id)}">Открыть заказ →</button></article>`).join(''):emptyState(orderFilter==='all'?'Здесь появятся ваши заказы':'Заказов в этом статусе нет',orderFilter==='all'?'Выберите товары в анализе и нажмите «Сформировать заказы». Мы разделим их по поставщикам.':'Выберите другой статус или создайте новый черновик из рекомендаций.',orderFilter==='all'?'orders':undefined);}
async function openOrder(id){try{const result=await api('/api/orders/item?id='+encodeURIComponent(id));activeOrder=result.order||result;renderOrderDetail();if(!$('#purchase-dialog').open)$('#purchase-dialog').showModal()}catch(e){toast(e.message)}}
function renderOrderDetail(){const o=activeOrder,draft=o.status==='draft';$('#purchase-detail').innerHTML=`<div class="dialog-heading"><div><div class="eyebrow">${esc(o.number||o.id)} · ${esc(o.supplier)}</div><h2>Заказ поставщику</h2></div><button class="icon-button" data-close-purchase aria-label="Закрыть заказ">×</button></div><div class="order-detail-meta"><span class="badge order-${esc(o.status)}">${esc(orderLabels[o.status])}</span><span>Создан ${dateText(o.created_at)}</span><span>${fmt(o.lines.length)} позиций</span></div>${o.warnings?.length?`<div class="notice warning"><strong>${draft?'Перед размещением проверьте':'Замечания на момент формирования'}</strong><ul>${o.warnings.map(w=>`<li>${esc(typeof w==='string'?w:w.message||w.reason)}</li>`).join('')}</ul></div>`:''}<form id="order-edit-form"><div class="form-grid"><label>Ожидаемая дата поступления<input id="order-eta" type="date" value="${esc(o.expected_at?.slice(0,10)||'')}" ${draft?'required':'disabled'}></label><label>Комментарий<input id="order-note" maxlength="1000" value="${esc(o.note||'')}" placeholder="Условия или причина корректировки" ${draft?'':'disabled'}></label></div><div class="table-scroll order-lines"><table><thead><tr><th>Товар</th><th class="num">Количество</th><th>Единица / партия</th><th>Обоснование</th></tr></thead><tbody>${o.lines.map((l,i)=>`<tr><td><button type="button" class="product-link product-title" data-item="${esc(l.item_id)}">${esc(l.article||l.code)}</button><div class="product-name">${esc(l.name)}</div></td><td class="num">${draft?`<label class="sr-only" for="order-qty-${i}">Количество ${esc(l.article||l.code)}</label><input id="order-qty-${i}" class="quantity-input" data-order-item="${esc(l.item_id)}" type="number" min="0" max="1000000000" step="any" required value="${Number(l.qty)}">`:fmt(l.qty,3)}</td><td>${esc(l.unit)}<div class="product-meta">Кратность ${fmt(l.pack,3)} · минимум ${fmt(l.moq,3)}</div></td><td class="line-reason">${esc(l.reason||'По расчёту потребности')}</td></tr>`).join('')}</tbody></table></div><div class="order-help">${draft?'Количество можно изменить. Ноль исключит позицию из поставки. Проверьте остатки, кратность, минимум и условия поставщика.':o.status==='approved'?'Заказ учитывается как ожидаемая поставка. При загрузке внешних поставок укажите этот номер заказа, чтобы не учитывать его дважды.':o.status==='received'?'Получение зарегистрировано, количество добавлено к остаткам. История заказа сохранена.':'Отменённый заказ остаётся в истории и не увеличивает ожидаемые поступления.'}</div><div class="dialog-actions split-actions"><div class="inline-actions"><button type="button" class="button secondary" data-export-order="xlsx">↓ Excel</button><button type="button" class="button secondary" data-export-order="csv">CSV</button></div><div class="inline-actions">${draft?'<button type="submit" class="button secondary">Сохранить правки</button><button type="button" class="button primary" data-transition="approved">Отметить размещение →</button>':o.status==='approved'?'<button type="button" class="button primary" data-transition="received">Подтвердить получение</button>':''}</div></div></form><details class="order-history"><summary>История изменений</summary><ol>${(o.events||[]).map(e=>`<li><span>${esc(e.at?new Date(e.at).toLocaleString('ru-RU'):'')}</span> ${esc(e.message||e.note||orderLabels[e.status]||e.action||e.type||'Изменение сохранено')}</li>`).join('')||'<li>Заказ создан</li>'}</ol></details>${['draft','approved'].includes(o.status)?'<button class="text-button danger-text" data-transition="cancelled">Отменить заказ</button>':''}`;$('#order-edit-form').addEventListener('submit',e=>{e.preventDefault();runButton(e.submitter,()=>saveOrder())});}
function draftPayload(){const form=$('#order-edit-form');if(!form.reportValidity())return null;return {id:activeOrder.id,expected_at:$('#order-eta').value,note:$('#order-note').value,lines:$$('[data-order-item]').map(n=>({item_id:n.dataset.orderItem,qty:Number(n.value)}))};}
async function saveOrder(){const payload=draftPayload();if(!payload)return;await api('/api/orders/update',payload);await refresh();await loadOrders();await openOrder(payload.id);toast('Изменения заказа сохранены');}
function showConfirmation({title,message,label,submit,action}){$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;$('#confirm-check-label').textContent=label;$('#confirm-submit').textContent=submit||'Подтвердить';$('#confirm-check').checked=false;$('#confirm-error').classList.add('hidden');confirmAction=action;$('#confirm-dialog').showModal();}
function transitionOrder(status){const o=activeOrder,payload=status==='approved'?draftPayload():null;if(status==='approved'&&!payload)return;const copy={approved:['Заказ размещён у поставщика?','Правки будут сохранены, заказ станет ожидаемой поставкой и уменьшит следующие рекомендации. Приложение не отправляет письмо поставщику.','Я проверил количество и условия и разместил заказ у поставщика.','Подтвердить размещение'],received:['Товар действительно поступил?','Количество всех позиций этого заказа будет добавлено к текущим остаткам. Если вы уже загрузили остатки с этим поступлением, не подтверждайте получение повторно.','Я сверил текущие остатки: это поступление ещё не учтено. Товары получены полностью.','Добавить в остатки'],cancelled:['Отменить заказ?','Заказ сохранится в истории. Его количество перестанет резервироваться и учитываться как ожидаемая поставка.','Подтверждаю отмену заказа.','Отменить заказ']}[status];showConfirmation({title:copy[0],message:copy[1],label:copy[2],submit:copy[3],action:async()=>{if(payload)await api('/api/orders/update',payload);await api('/api/orders/status',{id:o.id,status,confirmed:true,stock_confirmed:status==='received'});invalidateBacktest();await refresh();await loadOrders();await openOrder(o.id);toast('Статус заказа: '+orderLabels[status]);}});}
async function download(path,body,filename){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify(body)});if(!response.ok){let d;try{d=await response.json()}catch{d={error:'Не удалось подготовить файл'}}throw Error(d.error)}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}

// Review spikes; load all candidate pages without silently hiding excess.
async function loadAnomalies(more=false){if(anomalyLoading)return;anomalyLoading=true;if(!more)$('#anomaly-content').innerHTML='<div class="loading-state">Проверяем всплески и влияние на заказ…</div>';try{const data=await api('/api/anomalies?limit=500&offset='+(more?anomalyData.items.length:0));anomalyData={...data,items:more?[...anomalyData.items,...data.items]:data.items};if(!more)anomalyPage=0;renderAnomalies()}catch(e){if(!more)$('#anomaly-content').innerHTML=emptyState('Не удалось проверить всплески',e.message);toast(e.message)}finally{anomalyLoading=false}}
function renderAnomalies(){const s=anomalyData.summary||{};$('#anomaly-summary').innerHTML=[['Товаров со всплесками',s.products],['Месяцев к проверке',s.candidate_months],['Разовых проектов',s.excluded],['Обычный спрос',s.kept]].map(([label,v])=>`<div class="compact-stat"><span>${label}</span><strong>${fmt(v)}</strong></div>`).join('');const q=$('#anomaly-search').value.toLowerCase().trim(),decision=$('#anomaly-filter').value,items=anomalyData.items.filter(r=>(decision==='all'||r.decision===decision)&&(!q||(r.name+' '+r.code+' '+r.article+' '+r.supplier).toLowerCase().includes(q)));anomalyPage=Math.min(anomalyPage,Math.max(0,Math.ceil(items.length/pageSize)-1));const rows=items.slice(anomalyPage*pageSize,(anomalyPage+1)*pageSize);$('#anomaly-content').innerHTML=(rows.length?`<div class="table-scroll"><table class="anomaly-table"><thead><tr><th>Товар и период</th><th class="num">Факт</th><th class="num">Регулярный спрос</th><th>Влияние на заказ</th><th>Ваше решение</th></tr></thead><tbody>${rows.map(r=>`<tr data-anomaly-id="${esc(r.id)}" data-anomaly-month="${esc(r.month)}"><td><button class="product-link" data-item="${esc(r.id)}"><span class="product-title">${esc(r.article||r.code)}</span><span class="product-name">${esc(r.name)}</span></button><div class="product-meta">${esc(r.supplier)} · ${esc(r.month)}</div><p class="anomaly-reason">${esc(r.reason)}</p></td><td class="num">${fmt(r.raw,2)}<small>${esc(r.unit)}</small></td><td class="num regular-number">${fmt(r.regular,2)}<small>${esc(r.unit)}</small></td><td><div class="before-after">${fmt(r.order_before)} <span>→</span> <strong>${fmt(r.order_after)}</strong></div><div class="product-meta">${esc(r.unit)} при очистке месяца</div></td><td class="decision-cell"><select class="anomaly-decision" aria-label="Решение для ${esc(r.article||r.code)} за ${esc(r.month)}"><option value="auto" ${r.decision==='auto'?'selected':''}>Автоматическая оценка</option><option value="exclude" ${r.decision==='exclude'?'selected':''}>Разовый проект</option><option value="keep" ${r.decision==='keep'?'selected':''}>Обычный спрос</option></select><input class="anomaly-note" aria-label="Комментарий к решению" placeholder="Комментарий (необязательно)" maxlength="500"><button class="text-button" data-save-anomaly>Сохранить решение</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('Всплесков по этим условиям нет','Измените фильтр или загрузите историю продаж. Спокойный спрос тоже полезный результат.'))+`<div class="table-note">${esc(anomalyData.explanation||'Слева — заказ при сохранении фактического объёма этого месяца. Справа — при очистке этого месяца. Остальные решения одинаковы. Не складывайте количества с разными единицами учёта.')}</div>${s.truncated?`<div class="load-more"><p>Загружено ${fmt(anomalyData.items.length)} из ${fmt(s.candidate_months)} месяцев. Поиск и фильтр действуют на загруженные строки.</p><button class="button secondary" id="anomaly-load-more">Загрузить следующие 500</button></div>`:''}`;$('#anomaly-page-info').textContent=items.length?`${anomalyPage*pageSize+1}–${Math.min((anomalyPage+1)*pageSize,items.length)} из ${fmt(items.length)} загруженных`:'Нет результатов';$('#anomaly-prev').disabled=!anomalyPage;$('#anomaly-next').disabled=(anomalyPage+1)*pageSize>=items.length;}
async function saveAnomaly(button){const row=button.closest('[data-anomaly-id]');await runButton(button,async()=>{await api('/api/anomalies/decision',{id:row.dataset.anomalyId,month:row.dataset.anomalyMonth,decision:row.querySelector('.anomaly-decision').value,note:row.querySelector('.anomaly-note').value});invalidateBacktest();await refresh();await loadAnomalies();toast('Решение сохранено. Спрос и заказ пересчитаны.');});}


// Historical validation keeps measurements in their own units.
function metricPercent(v){return v===null||v===undefined?'—':fmt(v,1)+'%';}
function renderBacktest(r){const methods=`<div class="content-card"><h2>Как читать результат</h2><p><strong>MAE</strong> — средняя ошибка количества на товар за месяц. <strong>WAPE</strong> — сумма абсолютных ошибок относительно фактических продаж. В обоих случаях меньше — лучше. Процент не рассчитывается, если суммарные продажи равны нулю.</p><ul class="quality-list">${(r.methodology||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>Границы проверки</h3><ul class="quality-list">${(r.limitations||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>`;if(r.status!=='ok'){$('#backtest-content').innerHTML=emptyState('Недостаточно истории для проверки','Для каждого проверяемого месяца нужны минимум '+(r.min_training_months||6)+' предыдущих месяцев. Загрузите более длинную историю или выберите другой период.')+methods;return}$('#backtest-content').innerHTML=`<div class="compact-stats"><div class="compact-stat"><span>Проверено прогнозов</span><strong>${fmt(r.samples)}</strong><small>товар × месяц</small></div><div class="compact-stat"><span>Товаров в проверке</span><strong>${fmt(r.products)}</strong></div><div class="compact-stat"><span>Проверяемый период</span><strong class="compact-text">${esc(r.evaluation_months.join(' · '))}</strong></div><div class="compact-stat"><span>Недостаточно данных</span><strong>${fmt((r.skipped?.missing_actual||0)+(r.skipped?.insufficient_history||0))}</strong><small>пропущено прогнозов</small></div></div><div class="backtest-units">${r.per_unit.map(u=>{const delta=u.wape_improvement_pp;return `<article class="content-card metric-comparison"><div class="comparison-heading"><h2>${esc(u.unit||'Единица не указана')}</h2><span>${fmt(u.samples)} прогнозов</span></div><table><thead><tr><th>Ошибка</th><th>StockPilot</th><th>Обычное среднее</th></tr></thead><tbody><tr><td>WAPE</td><td class="metric-value">${metricPercent(u.model.wape)}</td><td>${metricPercent(u.baseline.wape)}</td></tr><tr><td>MAE</td><td class="metric-value">${fmt(u.model.mae,2)} ${esc(u.unit)}</td><td>${fmt(u.baseline.mae,2)} ${esc(u.unit)}</td></tr></tbody></table><p class="comparison-verdict ${delta>0?'green':delta<0?'orange':''}">${delta===null||delta===undefined?'Недостаточно ненулевых продаж для процентного сравнения.':delta>0?'Ошибка StockPilot ниже на '+fmt(delta,1)+' п. п.':delta<0?'Обычное среднее точнее на '+fmt(-delta,1)+' п. п.':'Одинаковая процентная ошибка.'}</p></article>`}).join('')}</div><details class="content-card"><summary>Результаты по месяцам</summary><div class="table-scroll"><table><thead><tr><th>Месяц</th><th>Единица</th><th>Прогнозов</th><th>StockPilot · WAPE</th><th>Среднее · WAPE</th></tr></thead><tbody>${(r.by_month||[]).map(m=>`<tr><td>${esc(m.month)}</td><td>${esc(m.unit)}</td><td>${fmt(m.samples)}</td><td>${metricPercent(m.model.wape)}</td><td>${metricPercent(m.baseline.wape)}</td></tr>`).join('')}</tbody></table></div></details><details class="content-card"><summary>Примеры наибольших ошибок</summary><div class="table-scroll"><table><thead><tr><th>Товар</th><th>Месяц</th><th>Факт</th><th>StockPilot</th><th>Среднее</th><th>Единица</th></tr></thead><tbody>${(r.examples||[]).map(e=>`<tr><td><button class="product-link" data-item="${esc(e.id)}">${esc(e.name)}</button><small>${esc(e.supplier)}</small></td><td>${esc(e.month)}</td><td>${fmt(e.actual,2)}</td><td>${fmt(e.predicted,2)}</td><td>${fmt(e.baseline,2)}</td><td>${esc(e.unit)}</td></tr>`).join('')}</tbody></table></div></details>${methods}`;}

// Guided mapping of sales, stock snapshots and dated shipments.
function resetAnalysis(){selectedIds.clear();$('#category-filter').value='';supplier='';page=0;currentId=null;chatHistory=[];$('#search').value='';$('#status-filter').value='all';$('#chat').innerHTML='<div class="assistant-message"><div class="chat-label">STOCKPILOT</div>Данные обновлены. Спросите о продажах и закупках в текущем анализе.</div>';invalidateBacktest();anomalyData={items:[],summary:{}};orderData={orders:[],summary:{}};}
function setImportBusy(value){importBusy=value;for(const id of ['import-submit','import-cancel','import-close'])$('#'+id).disabled=value;$('#import-submit').textContent=value?'Применяем и пересчитываем…':'Применить и пересчитать →';}
function startUpload(kind){if(!state)return toast('Подождите загрузки приложения');if(importBusy||busy)return toast('Дождитесь завершения текущего запроса');uploadKind=kind;$('#upload-file').click();}
function uploadStatus(text,error=false){for(const id of ['upload-status','data-upload-status']){const el=$('#'+id);el.textContent=text;el.classList.toggle('error',error);}}
async function chooseUpload(file){if(!file||importBusy)return;if(!state)return toast('Подождите загрузки приложения');if(busy)return toast('Дождитесь ответа ИИ перед сменой данных');if(!/\.(xlsx|csv)$/i.test(file.name)||!file.size||file.size>20*1024*1024)return uploadStatus('Нужен непустой файл .xlsx или .csv размером до 20 МБ.',true);importBusy=true;$('#choose-file').disabled=true;uploadStatus('Читаем файл и определяем столбцы…');try{const response=await fetch('/api/import/preview',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-CSRF-Token':state.csrf,'X-File-Name':encodeURIComponent(file.name),'X-Import-Kind':uploadKind},body:file});const result=await response.json();if(!response.ok)throw Error(result.error||'Не удалось прочитать файл');uploadPreview=result;$('#import-title').textContent=sourceLabels[uploadKind]+': проверим столбцы';$('#import-file-info').textContent=result.file+' · '+fmt(file.size/1024,1)+' КБ';$('#import-sheet').innerHTML=result.sheets.map((s,i)=>`<option value="${i}">${esc(/\.csv$/i.test(result.file)?'Таблица CSV':s.name)} · ${fmt(s.rows)} строк</option>`).join('');const preferred=result.sheets.findIndex(s=>s.mapping.code!==null&&(uploadKind==='sales'?(Object.keys(s.monthly||{}).length||s.mapping.date!==null&&s.mapping.qty!==null):uploadKind==='stock'?s.mapping.stock!==null:s.mapping.transit!==null));$('#import-sheet').value=String(Math.max(0,preferred));$('#import-date').value=result.as_of||state.settings.as_of;$('#import-supplier').value='';$('#import-mode-field').classList.toggle('hidden',uploadKind!=='sales');$('#import-semantics').textContent={sales:'Файл заменит историю продаж в вашем загруженном наборе. Ранее отдельно загруженные остатки и поставки, а также история заказов сохранятся — даже если сейчас открыт тестовый пример. Их даты не обновятся автоматически: проверьте актуальность и при необходимости загрузите свежие снимки. Данные кейса сохраняются. Без остатка доступен анализ спроса, но не количество заказа.',stock:'Полный снимок остатков: все отсутствующие в файле товары получат неизвестный остаток — не ноль. Указывайте свободное количество, доступное для продажи. Дата остатка должна соответствовать снимку.',transit:'Полный снимок поставок: предыдущие ожидаемые поставки будут заменены. Каждый приход — отдельная строка с датой. Для размещённых в StockPilot заказов укажите «Номер заказа», чтобы не учитывать одно поступление дважды.'}[uploadKind];renderImportSheet();$('#import-error').classList.add('hidden');$('#import-dialog').showModal();uploadStatus('Файл прочитан. Проверьте столбцы перед сохранением.')}catch(err){uploadStatus(err.message,true)}finally{importBusy=false;$('#choose-file').disabled=false;$('#upload-file').value=''}}
function renderImportSheet(){const sheet=uploadPreview.sheets[Number($('#import-sheet').value)];$('#import-mode').value=sheet.mode==='monthly'?'monthly':'transactions';const columns=sheet.columns.slice(0,10);$('#import-preview').innerHTML=`<table><caption>Первые ${sheet.sample.length} строки${sheet.columns.length>10?' · первые 10 столбцов':''}</caption><thead><tr>${columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${sheet.sample.map(row=>'<tr>'+row.slice(0,10).map(v=>`<td>${esc(v)}</td>`).join('')+'</tr>').join('')}</tbody></table>`;renderMapping();}
function renderMapping(){const sheet=uploadPreview.sheets[Number($('#import-sheet').value)],monthly=uploadKind==='sales'&&$('#import-mode').value==='monthly',required=uploadKind==='sales'?(monthly?['code']:['code','date','qty']):uploadKind==='stock'?['code','stock']:['code','transit','eta'];const field=f=>`<label>${esc(f.label)}${required.includes(f.key)?' <span class="required-star">*</span>':''}<select data-field="${f.key}" ${required.includes(f.key)?'required':''}><option value="">${required.includes(f.key)?'Выберите столбец':'Не указан'}</option>${sheet.columns.map((c,i)=>monthly&&Object.hasOwn(sheet.monthly||{},String(i))?'':`<option value="${i}" ${sheet.mapping[f.key]===i?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`;$('#required-mapping').innerHTML=uploadPreview.fields.filter(f=>required.includes(f.key)).map(field).join('');$('#optional-mapping').innerHTML=uploadPreview.fields.filter(f=>!required.includes(f.key)&&!(monthly&&['date','qty','order_id'].includes(f.key))).map(field).join('');$('#optional-count').textContent='· распознано '+$$('#optional-mapping select').filter(s=>s.value!=='').length;$('#monthly-info').classList.toggle('hidden',!monthly);$('#monthly-info').textContent=Object.keys(sheet.monthly||{}).length?'Распознано месяцев: '+Object.keys(sheet.monthly).length+'. Все столбцы месяцев будут использованы; пустые ячейки считаются нулём.':'Столбцы месяцев не распознаны. Нужны заголовки «2026-01» или «Январь 2026».';}
async function switchDataset(mode){if(busy||importBusy)return toast('Дождитесь завершения текущего запроса');importBusy=true;try{await api('/api/dataset',{mode});resetAnalysis();await refresh();showView('orders');toast('Набор данных переключён')}catch(err){toast(err.message)}finally{importBusy=false}}
function openSettings(){if(!state)return;const f=$('#settings-form');for(const [key,value]of Object.entries(state.settings)){if(f.elements[key]){if(typeof value==='boolean')f.elements[key].checked=value;else if(typeof value!=='object')f.elements[key].value=value}}$('#policy-category').innerHTML='<option value="">Без изменения правил</option>'+state.categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');$('#policy-safety').value='';$('#policy-growth').value='';const suppliers=[...new Set(state.rows.map(r=>r.supplier))];$('#supplier-policies').innerHTML=suppliers.map(name=>{const p=state.settings.supplier_policies?.[name]||{};return `<fieldset class="supplier-policy" data-policy-supplier="${esc(name)}"><legend>${esc(name)}</legend><div class="form-grid"><label>Срок, дней<input data-supplier-key="lead_days" type="number" min="1" max="180" value="${p.lead_days??''}" placeholder="${state.settings.lead_days}"></label><label>Цикл, дней<input data-supplier-key="review_days" type="number" min="1" max="90" value="${p.review_days??''}" placeholder="${state.settings.review_days}"></label><label>Запас, дней<input data-supplier-key="safety_days" type="number" min="0" max="90" value="${p.safety_days??''}" placeholder="${state.settings.safety_days}"></label></div></fieldset>`}).join('');$('#settings-dialog').showModal();}


// One delegated controller for dynamic rows and action buttons.
$$('.nav').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
document.addEventListener('click',e=>{const view=e.target.closest('[data-open-view]');if(view)showView(view.dataset.openView);const upload=e.target.closest('[data-upload-kind]');if(upload)startUpload(upload.dataset.uploadKind);const item=e.target.closest('[data-item]');if(item)openItem(item.dataset.item);const order=e.target.closest('[data-order-id]');if(order)openOrder(order.dataset.orderId);const status=e.target.closest('[data-order-status]');if(status){orderFilter=status.dataset.orderStatus;renderOrders()}const close=e.target.closest('[data-close-purchase]');if(close)$('#purchase-dialog').close();const transition=e.target.closest('[data-transition]');if(transition)transitionOrder(transition.dataset.transition);const exp=e.target.closest('[data-export-order]');if(exp)runButton(exp,()=>download('/api/orders/export',{id:activeOrder.id,format:exp.dataset.exportOrder},'StockPilot_'+(activeOrder.number||'order')+'.'+exp.dataset.exportOrder),'Готовим…');const anomaly=e.target.closest('[data-save-anomaly]');if(anomaly)saveAnomaly(anomaly);if(e.target.closest('#anomaly-load-more'))loadAnomalies(true);});
$('#rows').addEventListener('change',e=>{const box=e.target.closest('[data-select-id]');if(!box)return;box.checked?selectedIds.add(box.dataset.selectId):selectedIds.delete(box.dataset.selectId);renderRows()});
$('#select-page').addEventListener('change',e=>{filtered.slice(page*pageSize,(page+1)*pageSize).filter(canOrder).forEach(r=>e.target.checked?selectedIds.add(r.id):selectedIds.delete(r.id));renderRows()});
$('#clear-selection').addEventListener('click',()=>{selectedIds.clear();renderRows()});
$('#create-orders').addEventListener('click',e=>runButton(e.target,async()=>{const ids=selectedIds.size?[...selectedIds]:filtered.filter(canOrder).map(r=>r.id),r=await api('/api/orders/create',{ids});selectedIds.clear();await refresh();showView('purchase');toast('Создано заказов: '+fmt(r.orders?.length||0)+(r.skipped?.length?'. Пропущено уже учтённых или недоступных позиций: '+fmt(r.skipped.length):''));},'Формируем…'));
for(const id of ['search','status-filter','category-filter'])$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=0;renderRows()});
$('#prev').addEventListener('click',()=>{page--;renderRows()});$('#next').addEventListener('click',()=>{page++;renderRows()});
$('#reset-filters').addEventListener('click',()=>{supplier='';page=0;$('#search').value='';$('#category-filter').value='';$('#status-filter').value='all';renderSuppliers();renderRows()});
$('#supplier-tabs').addEventListener('click',e=>{const b=e.target.closest('.supplier');if(b){supplier=b.dataset.supplier;page=0;renderSuppliers();renderRows()}});
for(const id of ['date-settings','settings-open'])$('#'+id).addEventListener('click',openSettings);
$('#policy-category').addEventListener('change',()=>{const p=state.settings.category_policies?.[$('#policy-category').value]||{};$('#policy-safety').value=p.safety_days??'';$('#policy-growth').value=p.growth_pct??''});
$('#settings-form').addEventListener('submit',e=>{e.preventDefault();runButton(e.submitter,async()=>{const f=e.target,settings=structuredClone(state.settings);for(const k of ['lead_days','review_days','safety_days','growth_pct'])settings[k]=Number(f.elements[k].value);settings.as_of=f.elements.as_of.value;for(const k of ['seasonality','trend','remove_outliers','compensate_stockouts'])settings[k]=f.elements[k].checked;settings.supplier_policies={};$$('[data-policy-supplier]').forEach(row=>{const policy={};row.querySelectorAll('[data-supplier-key]').forEach(n=>{if(n.value!=='')policy[n.dataset.supplierKey]=Number(n.value)});if(Object.keys(policy).length)settings.supplier_policies[row.dataset.policySupplier]=policy});const cat=$('#policy-category').value;if(cat){const policy={};if($('#policy-safety').value!=='')policy.safety_days=Number($('#policy-safety').value);if($('#policy-growth').value!=='')policy.growth_pct=Number($('#policy-growth').value);settings.category_policies||={};settings.category_policies[cat]=policy}await api('/api/calculate',settings);invalidateBacktest();await refresh();$('#settings-dialog').close();toast('Рекомендации пересчитаны с новыми условиями.');},'Пересчитываем…')});
$$('#settings-dialog .close-dialog').forEach(b=>b.addEventListener('click',()=>$('#settings-dialog').close()));
$('#export').addEventListener('click',e=>runButton(e.target,()=>download('/api/export',{ids:filtered.map(r=>r.id)},'StockPilot_расчёт_'+state.settings.as_of+'.csv'),'Готовим…'));
$('#chat-form').addEventListener('submit',e=>{e.preventDefault();sendMessage($('#message').value)});$('#message').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage(e.target.value)}});$$('[data-prompt]').forEach(b=>b.addEventListener('click',()=>sendMessage(b.dataset.prompt)));
$('#choose-file').addEventListener('click',()=>startUpload('sales'));$('#new-upload').addEventListener('click',()=>showView('quality'));$('#upload-file').addEventListener('change',e=>chooseUpload(e.target.files[0]));
let dragDepth=0;$('#dropzone').addEventListener('dragenter',e=>{e.preventDefault();dragDepth++;$('#dropzone').classList.add('dragging')});$('#dropzone').addEventListener('dragover',e=>e.preventDefault());$('#dropzone').addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;$('#dropzone').classList.remove('dragging')}});$('#dropzone').addEventListener('drop',e=>{e.preventDefault();dragDepth=0;$('#dropzone').classList.remove('dragging');if(e.dataTransfer.files.length>1)return uploadStatus('Выберите один файл с продажами.',true);uploadKind='sales';chooseUpload(e.dataTransfer.files[0])});
$('#import-sheet').addEventListener('change',renderImportSheet);$('#import-mode').addEventListener('change',renderMapping);for(const id of ['import-close','import-cancel'])$('#'+id).addEventListener('click',()=>{if(!importBusy)$('#import-dialog').close()});$('#import-dialog').addEventListener('cancel',e=>{if(importBusy)e.preventDefault()});
$('#import-form').addEventListener('submit',async e=>{e.preventDefault();if(importBusy||!uploadPreview)return;setImportBusy(true);$('#import-error').classList.add('hidden');const mapping={};$$('[data-field]').forEach(s=>mapping[s.dataset.field]=s.value===''?null:Number(s.value));try{await api('/api/import/commit',{token:uploadPreview.token,kind:uploadKind,sheet:Number($('#import-sheet').value),mode:$('#import-mode').value,as_of:$('#import-date').value,supplier:$('#import-supplier').value.trim(),mapping});resetAnalysis();await refresh();$('#import-dialog').close();uploadStatus(sourceLabels[uploadKind]+' сохранены. Рекомендации пересчитаны.');showView(uploadKind==='sales'?'quality':'orders');toast(uploadKind==='sales'?'Продажи готовы. Теперь добавьте остатки и ожидаемые поставки.':'Данные применены. Анализ обновлён.')}catch(err){$('#import-error').textContent=err.message;$('#import-error').classList.remove('hidden');$('#import-error').scrollIntoView({block:'nearest'})}finally{setImportBusy(false)}});
$('#restore-original').addEventListener('click',()=>switchDataset('partner'));$('#restore-upload').addEventListener('click',()=>switchDataset('upload'));$('#open-demo').addEventListener('click',()=>switchDataset('demo'));
$('#purchase-refresh').addEventListener('click',()=>loadOrders());$('#anomaly-refresh').addEventListener('click',()=>loadAnomalies());$('#anomaly-search').addEventListener('input',()=>{anomalyPage=0;renderAnomalies()});$('#anomaly-filter').addEventListener('change',()=>{anomalyPage=0;renderAnomalies()});$('#anomaly-prev').addEventListener('click',()=>{anomalyPage--;renderAnomalies()});$('#anomaly-next').addEventListener('click',()=>{anomalyPage++;renderAnomalies()});
for(const id of ['confirm-close','confirm-cancel'])$('#'+id).addEventListener('click',()=>$('#confirm-dialog').close());
$('#confirm-form').addEventListener('submit',async e=>{e.preventDefault();if(!confirmAction)return;const button=$('#confirm-submit'),text=button.textContent;button.disabled=true;button.textContent='Выполняем…';$('#confirm-error').classList.add('hidden');try{await confirmAction();$('#confirm-dialog').close();confirmAction=null}catch(err){$('#confirm-error').textContent=err.message;$('#confirm-error').classList.remove('hidden')}finally{button.disabled=false;button.textContent=text}});
$('#backtest-form').addEventListener('submit',e=>{e.preventDefault();runButton(e.submitter,async()=>{$('#backtest-content').innerHTML='<div class="loading-state">Проверяем каждый месяц по доступной на тот момент истории…</div>';try{backtestResult=await api('/api/backtest',{months:Number($('#backtest-months').value)});renderBacktest(backtestResult)}catch(error){$('#backtest-content').innerHTML=emptyState('Не удалось завершить проверку',error.message);throw error}},'Проверяем…')});
$('#automation-form').addEventListener('submit',e=>{e.preventDefault();runButton(e.submitter,async()=>{const f=e.target;await api('/api/automation',{enabled:f.elements.enabled.checked,interval_minutes:Number(f.elements.interval_minutes.value),advance_date:f.elements.advance_date.checked,folder:f.elements.folder.value.trim()});await refresh();renderAutomation(true);toast('Настройки обновления сохранены');})});
$('#automation-run').addEventListener('click',e=>runButton(e.target,async()=>{const f=$('#automation-form');await api('/api/automation',{enabled:f.elements.enabled.checked,interval_minutes:Number(f.elements.interval_minutes.value),advance_date:f.elements.advance_date.checked,folder:f.elements.folder.value.trim()});await api('/api/automation/run',{});resetAnalysis();await refresh();toast('Обновление завершено. Рекомендации пересчитаны.');},'Обновляем…'));
refresh().then(()=>{if(state.mode==='upload'){$('#status-filter').value='all';renderRows()}showView(location.hash.slice(1)||'home')}).catch(err=>{$('#stats').textContent='Не удалось загрузить расчёт: '+err.message;uploadStatus('Не удалось подключиться к приложению. Проверьте запуск и обновите страницу.',true);toast(err.message)});
